import kotlinx.coroutines.*

fun main() = runBlocking {
    val scope = CoroutineScope(SupervisorJob())
    val job = scope.launch {
        try { delay(1000); println("loaded") }
        finally { println("cleanup") }
    }
    delay(50)
    scope.cancel()
    job.join()
    scope.launch { println("late") }
    delay(50)
    println("cancelled=${job.isCancelled}")
}

import kotlinx.coroutines.*

fun main() = runBlocking {
    val handler = CoroutineExceptionHandler { _, e ->
        println("caught ${e.message}")
    }
    val scope = CoroutineScope(SupervisorJob() + handler)
    val a = scope.launch { delay(10); error("boom") }
    val b = scope.launch { delay(100); println("b done") }
    joinAll(a, b)
    println("active=${scope.isActive}")
}

import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*

fun main() = runBlocking {
    val names = MutableStateFlow("Ann")
    val count = MutableStateFlow(1)
    withTimeoutOrNull(100) {
        names.collect { println("name=$it") }
        count.collect { println("count=$it") }
    }
    println("stopped")
}

import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*

fun main() = runBlocking {
    val state = MutableStateFlow(0)
    repeat(2) { round ->
        val job = launch { state.collect { println("r$round:$it") } }
        delay(10)
        state.value++
        delay(10)
        job.cancel()
        state.value++
    }
}
